                //  2: 4/6,\n                                                              //  3: 4/7,\n                                                              //  4: 4/8]\n#define LORA_PREAMBLE_LENGTH                        8         // Same for Tx and Rx\n#define LORA_SYMBOL_TIMEOUT                         5         // Symbols\n#define LORA_FIX_LENGTH_PAYLOAD_ON                  false\n#define LORA_IQ_INVERSION_ON                        false\n\nstatic RadioEvents_t RadioEvents;\n\nstatic const char *TAG = "app_main";\n\nvoid OnTxDone( void )\n{\n    ESP_LOGI(TAG, "OnTxDone");\n}\n\nvoid demo_lora_tx(void)\n{\n    int cnt = 0;\n    ESP_LOGI(TAG, "system start");\n    ESP_LOGI(TAG, "demo lora tx");\n    ESP_ERROR_CHECK(bsp_board_init());\n\n    RadioEvents.TxDone = OnTxDone;\n    Radio.Init( &RadioEvents );\n\n    Radio.SetChannel( RF_FREQUENCY );\n    Radio.SetTxConfig( MODEM_LORA,22, 0, LORA_BANDWIDTH,\n                                   LORA_SPREADING_FACTOR, LORA_CODINGRATE,\n                                   LORA_PREAMBLE_LENGTH, LORA_FIX_LENGTH_PAYLOAD_ON,\n                                   true, 0, 0, LORA_IQ_INVERSION_ON, 3000 );\n\n    Radio.SetMaxPayloadLength( MODEM_LORA, 255 );\n\n    while(1) {\n        printf("send... %d\\n", cnt++);\n        Radio.Send( "1234567890", sizeof("1234567890") );\n        vTaskDelay(5000 / portTICK_PERIOD_MS);\n    }\n}\n'})}),"\n",(0,i.jsx)(n.h2,{id:"receber-pacotes-de-dados",children:(0,i.jsx)(n.strong,{children:"Receber Pacotes de Dados"})}),"\n",(0,i.jsx)(n.p,{children:"Este c\xf3digo de exemplo configura um receptor LoRa\xae usando o m\xf3dulo de r\xe1dio SX126x e registra os pacotes recebidos no console. Ele pode ser usado como ponto de partida para desenvolver aplica\xe7\xf5es LoRa\xae que exijam recebimento de dados a longas dist\xe2ncias com baixo consumo de energia."}),"\n",(0,i.jsx)(n.pre,{children:(0,i.jsx)(n.code,{className:"language-c",children:'#include <stdio.h>\n#include <string.h>\n#include <stdli